// Original selected application renderer; generated by prepare_home_scene_render_controls.py.
namespace Zjcs.Official.HomeSceneUiControls
{
using Object = UnityEngine.Object;
using UnityEngine;

[ExecuteInEditMode]
public class SpriteRendererGroup : MonoBehaviour
{
	[Range(0f, 1f)]
	public float Alpha = 1f;

	public Material Mat;

	private MaterialPropertyBlock mMPB;

	private SpriteRenderer[] mSRs;

	private static readonly int sAlphaID = Shader.PropertyToID("_ExtraAlpha");

	private MaterialPropertyBlock MPB
	{
		get
		{


			if (mMPB == null)
			{
				mMPB = new MaterialPropertyBlock();
			}
			return mMPB;
		}
	}

	private void Awake()
	{
		ApplyMaterial();
		RefreshMat();
	}

	private void OnDidApplyAnimationProperties()
	{
		RefreshMat();
	}

	[ContextMenu("Apply Material")]
	private void ApplyMaterial()
	{
		mSRs = ((Component)this).GetComponentsInChildren<SpriteRenderer>(true);
		SpriteRenderer[] array = mSRs;
		for (int i = 0; i < array.Length; i++)
		{
			((Renderer)array[i]).sharedMaterial = Mat;
		}
	}

	private void RefreshMat()
	{
		if (mSRs != null)
		{
			int i = 0;
			for (int num = mSRs.Length; i < num; i++)
			{
				MPB.Clear();
				((Renderer)mSRs[i]).GetPropertyBlock(MPB);
				MPB.SetFloat(sAlphaID, Alpha);
				((Renderer)mSRs[i]).SetPropertyBlock(MPB);
			}
		}
	}
}

}
